const kpis = $('kpi_semanais').all().map(i => i.json)
  .sort((a, b) => b.semana_referencia.localeCompare(a.semana_referencia));
const iniciativas = $('iniciativa_status').all().map(i => i.json);
const thresholds = $('alertas_thresholds').all().map(i => i.json);

const atual = kpis[0];
const anterior = kpis[1];

const campos = ["receita_liquida","margem_pct","cac_medio","csat_medio",
                "custo_atendimento_semanal","skus_criticos","tickets_automatizados_pct"];

const deltas = {};
for (const campo of campos) {
  const atual_v = Number(atual[campo]);
  const anterior_v = Number(anterior[campo]);
  deltas[campo] = {
    atual: atual_v,
    anterior: anterior_v,
    variacao_pct: anterior_v !== 0
      ? Math.round(((atual_v - anterior_v) / anterior_v) * 1000) / 10
      : null
  };
}

const alertas = [];
for (const t of thresholds) {
  const valor_atual = deltas[t.kpi_nome]?.atual;
  if (valor_atual == null) continue;
  if (t.direcao === "abaixo_de_min_e_alerta" && t.limite_min && valor_atual < Number(t.limite_min)) {
    alertas.push(`${t.kpi_nome} está em ${valor_atual}, abaixo do mínimo aceitável (${t.limite_min})`);
  }
  if (t.direcao === "acima_de_max_e_alerta" && t.limite_max && valor_atual > Number(t.limite_max)) {
    alertas.push(`${t.kpi_nome} está em ${valor_atual}, acima do máximo aceitável (${t.limite_max})`);
  }
}

return [
  {
    json: {
      semana_referencia: atual.semana_referencia,
      deltas,
      alertas,
      iniciativas
    }
  }
];

const raw = $json.text; // troque 'text' pelo nome real do campo, se for diferente

const ICONS = {
  "RESUMO": "📌",
  "VARIAÇÕES": "📈",
  "ALERTAS": "⚠️",
  "INICIATIVAS EM ANDAMENTO": "🛠️",
  "IMPACTO REALIZADO VS PROJETADO": "💰",
  "RECOMENDAÇÃO": "✅"
};

function inlineFormat(text) {
  return text
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/(?<!\*)\*([^*]+)\*(?!\*)/g, '<em>$1</em>');
}

const headerRegex = /^\s*(?:#{1,6}\s*)?\*{0,2}\s*\d+[\.\-\)]\s*([A-ZÀ-Ü][A-ZÀ-Ü0-9\s/]+?)\*{0,2}\s*$/;
const bulletRegex = /^\s*[\*\-•]\s+(.*)$/;

const linhas = raw.split('\n');
const blocos = [];
let atual = null;

for (const linhaBruta of linhas) {
  const linha = linhaBruta.trimEnd();
  if (linha.trim() === '') continue;

  const headerMatch = linha.match(headerRegex);
  if (headerMatch) {
    if (atual) blocos.push(atual);
    atual = { titulo: headerMatch[1].trim(), linhas: [] };
    continue;
  }

  if (!atual) continue;
  atual.linhas.push(linha);
}
if (atual) blocos.push(atual);

function blockToHtml({ titulo, linhas }) {
  const icon = ICONS[titulo] || "•";
  const isRecomendacao = titulo === "RECOMENDAÇÃO";
  const isAlertas = titulo === "ALERTAS";

  const bulletLines = linhas.filter(l => bulletRegex.test(l));
  const isList = bulletLines.length === linhas.length && linhas.length > 0;

  let innerHtml;
  if (isList) {
    const items = linhas.map(l => {
      const m = l.match(bulletRegex);
      return `<li style="margin-bottom:6px; color:#374151;">${inlineFormat(m[1])}</li>`;
    }).join('');
    innerHtml = `<ul style="margin:0; padding-left:18px; font-size:13.5px; line-height:1.7;">${items}</ul>`;
  } else {
    innerHtml = linhas.map(l => {
      const semMarcador = l.replace(bulletRegex, '$1');
      return `<p style="margin:0 0 8px; color:#374151; font-size:13.5px; line-height:1.7;">${inlineFormat(semMarcador)}</p>`;
    }).join('');
  }

  const bgColor = isRecomendacao ? "#F3F0FF" : "#FFFFFF";
  const borderColor = isRecomendacao ? "#8575FF" : (isAlertas ? "#F2B100" : "#EEECFF");
  const titleColor = isRecomendacao ? "#2A0090" : "#131920";

  return `
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:${bgColor}; border:1px solid ${borderColor}; border-left:4px solid ${borderColor}; border-radius:8px; margin-bottom:14px;">
      <tr>
        <td style="padding:16px 20px;">
          <div style="font-size:13px; font-weight:700; color:${titleColor}; text-transform:uppercase; letter-spacing:.3px; margin-bottom:10px;">
            ${icon}&nbsp; ${titulo}
          </div>
          ${innerHtml}
        </td>
      </tr>
    </table>`;
}

const html_relatorio = blocos.map(blockToHtml).join('');

return [{ json: { ...$json, html_relatorio } }];

const kb = $('base_conhecimento1').all().map(i => i.json);
const kbTexto = kb.map(e => `[${e.categoria}] P: ${e.pergunta_referencia} R: ${e.resposta_padrao}`).join('\n');

// busca a mensagem direto no nó do Chat Trigger (ajuste o nome exato entre aspas se for diferente)
const mensagem = $('When chat message received').first().json.chatInput;
const match = mensagem.match(/ORD-\d+/i);

let pedidoInfo = "Nenhum número de pedido foi informado ou reconhecido na mensagem.";

if (match) {
  const orderId = match[0].toUpperCase();
  const pedidos = $('pedidos_rastreio').all().map(i => i.json);
  const pedido = pedidos.find(p => p.order_id === orderId);

  if (pedido) {
    pedidoInfo = `Pedido ${pedido.order_id}: status atual "${pedido.status_rastreio}", transportadora ${pedido.transportadora}, pedido feito em ${pedido.data_pedido}.`;
  } else {
    pedidoInfo = `O cliente mencionou o pedido ${orderId}, mas ele não foi encontrado na base.`;
  }
}

// modo "Run Once for All Items" -> precisa devolver um ARRAY
return [
  {
    json: {
      chatInput: mensagem,
      base_conhecimento_texto: kbTexto,
      pedido_info: pedidoInfo
    }
  }
];

