const raw = $json.text; // ajuste 'text' pro nome real do campo de saída do LLM

// remove ```json ... ``` caso o modelo tenha envolvido a resposta em bloco de código
const limpo = raw.replace(/```json\s*|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(limpo);
} catch (e) {
  // fallback: se não veio JSON válido, mostra o texto cru mesmo, sem quebrar o chat
  parsed = { categoria: "desconhecida", resposta: raw };
}

return [
  {
    json: {
      text: parsed.resposta,                  // isso é o que aparece na tela do chat
      categoria_detectada: parsed.categoria    // fica disponível no item, mas não aparece no chat
    }
  }
];

const op = $input.item.json;

// Google Sheets manda números como texto — convertendo
const impacto_medio_reais = Number(op.impacto_medio_reais);
const esforco_nivel = Number(op.esforco_nivel);
const janela_dias = Number(op.janela_dias);
const nota_estrategica_manual = Number(op.nota_estrategica_manual);

function impactoTier() {
  if (impacto_medio_reais === 0) return nota_estrategica_manual;
  if (impacto_medio_reais >= 1500000) return 5;
  if (impacto_medio_reais >= 500000) return 4;
  if (impacto_medio_reais >= 150000) return 3;
  return 2;
}

function velocidadeTier() {
  if (janela_dias <= 30) return 5;
  if (janela_dias <= 60) return 4;
  if (janela_dias <= 75) return 3;
  return 2;
}

const impacto_tier = impactoTier();
const facilidade_tier = 6 - esforco_nivel;
const velocidade_tier = velocidadeTier();

const W_IMPACTO = 0.5, W_FACILIDADE = 0.3, W_VELOCIDADE = 0.2;
const score = (W_IMPACTO * impacto_tier + W_FACILIDADE * facilidade_tier + W_VELOCIDADE * velocidade_tier) * 20;

return {
  json: {
    ...op,
    impacto_tier,
    facilidade_tier,
    velocidade_tier,
    score: Math.round(score * 10) / 10
  }
};

const raw = $json.text; // ajuste 'text' pro nome real do campo de saída do LLM
const limpo = raw.replace(/```json\s*|```/g, '').trim();

let justificativas;
try {
  justificativas = JSON.parse(limpo);
} catch (e) {
  justificativas = [];
}

const mapaJustificativa = {};
for (const j of justificativas) {
  mapaJustificativa[j.id] = j.justificativa;
}

// busca a lista ORIGINAL (já ordenada) direto no nó Sort — ajuste o nome se for diferente
const rankeadas = $('Sort').all().map(i => i.json);

function corTipo(tipo) {
  return tipo === 'quick_win'
    ? { bg: '#e6f5eb', text: '#00802f', label: 'Quick Win' }
    : { bg: '#eeecff', text: '#2a0090', label: 'Estruturante' };
}

function formatReais(v) {
  const num = Number(v);
  if (num === 0) return 'Direcional (sem R$ direto)';
  return 'R$ ' + num.toLocaleString('pt-BR', { maximumFractionDigits: 0 });
}

const linhas = rankeadas.map((op, idx) => {
  const cor = corTipo(op.tipo);
  const justificativa = mapaJustificativa[op.id] || "Sem justificativa gerada.";
  const barraLargura = Math.round(op.score);
  return `
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#ffffff; border:1px solid #eeecff; border-radius:8px; margin-bottom:12px;">
      <tr>
        <td style="padding:16px 20px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
            <tr>
              <td style="font-size:14px; font-weight:700; color:#131920;">${idx + 1}. ${op.nome}</td>
              <td align="right"><span style="font-size:11px; font-weight:700; padding:3px 10px; border-radius:999px; background-color:${cor.bg}; color:${cor.text};">${cor.label}</span></td>
            </tr>
          </table>
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:10px 0 8px;">
            <tr>
              <td style="background-color:#f3f0ff; border-radius:6px; height:8px;">
                <table role="presentation" cellpadding="0" cellspacing="0" style="height:8px;"><tr><td style="background-color:#4200db; width:${barraLargura * 2}px; height:8px; border-radius:6px;"></td></tr></table>
              </td>
            </tr>
          </table>
          <div style="font-size:12.5px; color:#656871; margin-bottom:6px;">Score: <strong style="color:#2a0090;">${op.score}</strong> · Impacto: ${formatReais(op.impacto_medio_reais)} · Janela: ${op.janela_dias} dias</div>
          <div style="font-size:13px; color:#374151;">${justificativa}</div>
        </td>
      </tr>
    </table>`;
}).join('');

return [
  {
    json: {
      html_relatorio: linhas
    }
  }
];

const items = $input.all().map(i => i.json);
const listaTexto = items.map(op =>
  `{"id": "${op.id}", "nome": "${op.nome}", "score": ${op.score}, "impacto_medio_reais": ${op.impacto_medio_reais}, "esforco_nivel": ${op.esforco_nivel}, "janela_dias": ${op.janela_dias}}`
).join(',\n');

return [
  {
    json: {
      lista_json: `[${listaTexto}]`
    }
  }
];
